    [pbr::OriginalName("BAG_FULL")] BagFull = 9,
    [pbr::OriginalName("LEVEL_TOO_LOW")] LevelTooLow = 10,
    [pbr::OriginalName("WRONG_SLOT")] WrongSlot = 11,
    [pbr::OriginalName("DAILY_LIMIT")] DailyLimit = 12,
