  /// <summary>
  /// ---- matches (the server simulates at 20 Hz; the client reports its own position and asks to use skills) --------------
  /// </summary>
  public enum EntityKind {
    [pbr::OriginalName("ENTITY_KIND_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// the character the player controls
    /// </summary>
    [pbr::OriginalName("PLAYER_CHARACTER")] PlayerCharacter = 1,
    /// <summary>
    /// a squad member the server controls
    /// </summary>
    [pbr::OriginalName("ALLY_AI")] AllyAi = 2,
    [pbr::OriginalName("BOSS")] Boss = 3,
    /// <summary>
    /// small mobs that swarm during a fight
    /// </summary>
    [pbr::OriginalName("MINION")] Minion = 4,
    /// <summary>
    /// a summoned egg (Namek) or similar
    /// </summary>
    [pbr::OriginalName("PET")] Pet = 5,
    /// <summary>
    /// a training dummy of the village: never fights back, refills its HP when it runs out
    /// </summary>
    [pbr::OriginalName("TRAINING_DUMMY")] TrainingDummy = 6,
  }

  public enum Effect {
    [pbr::OriginalName("EFFECT_NONE")] None = 0,
    [pbr::OriginalName("STUN")] Stun = 1,
    [pbr::OriginalName("HOLD")] Hold = 2,
    [pbr::OriginalName("SLEEP")] Sleep = 3,
    [pbr::OriginalName("SHIELD")] Shield = 4,
    [pbr::OriginalName("CHOCOLATE")] Chocolate = 5,
    [pbr::OriginalName("REGEN")] Regen = 6,
    [pbr::OriginalName("BUFF")] Buff = 7,
    /// <summary>
    /// an area that will hit after duration_ms (boss ultimate): x, y, dir, length, width
    /// </summary>
    [pbr::OriginalName("TELEGRAPH_RECT")] TelegraphRect = 8,
    [pbr::OriginalName("TELEGRAPH_CIRCLE")] TelegraphCircle = 9,
    /// <summary>
    /// charging or gong before a skill (duration_ms)
    /// </summary>
    [pbr::OriginalName("CAST_START")] CastStart = 10,
    [pbr::OriginalName("TELEPORT")] Teleport = 11,
    [pbr::OriginalName("ENRAGE")] Enrage = 12,
    /// <summary>
    /// a cast, a gong or a channel ended (finished or broken): the client stops the pose (skill_id, source_id)
    /// </summary>
    [pbr::OriginalName("CAST_END")] CastEnd = 13,
    /// <summary>
    /// Ma phong ba: the target is sucked into the jar (target_id, source_id, duration_ms until it comes out as a jar, x, y = the jar)
    /// </summary>
    [pbr::OriginalName("MAFUBA_GATHER")] MafubaGather = 14,
    /// <summary>
    /// Ma phong ba: the target is a jar for duration_ms (it takes damage every 500 ms and cannot act)
    /// </summary>
    [pbr::OriginalName("JAR")] Jar = 15,
    /// <summary>
    /// Super Kamejoko / Cađíc: the beam hits for duration_ms from x, y along dir; length and width of the rectangle
    /// </summary>
    [pbr::OriginalName("ULTIMATE_BEAM")] UltimateBeam = 16,
    /// <summary>
    /// (against small monsters in a dungeon it turns once around the caster: see spin_deg_per_s of EffectEvent)
    /// </summary>
    [pbr::OriginalName("WAVE")] Wave = 17,
    /// <summary>
    /// dungeon: the last monster of the stage fell, the boss comes (target_id = the boss, x, y = where it stands)
    /// </summary>
    [pbr::OriginalName("BOSS_COMING")] BossComing = 18,
    /// <summary>
    /// dungeon: a boss calls a small monster (source_id = the boss, target_id = the monster, x, y)
    /// </summary>
    [pbr::OriginalName("SUMMON")] Summon = 19,
    /// <summary>
    /// dungeon: a boss turned into its next form (target_id = the boss, skill_id = the form now, 1 based, length = how many forms; the new look comes as an EntitySpawn of the same id)
    /// </summary>
    [pbr::OriginalName("BOSS_EVOLVE")] BossEvolve = 21,
    /// <summary>
    /// an entity died (target_id = who, source_id = what killed it, x, y = where; dir = the way the blow came)
    /// </summary>
    [pbr::OriginalName("DIED")] Died = 20,
  }

